	POINT_ANTI_RESIST_MAGIC,	// 252
	// MT2009_PLUS_BONUS67_WIKI_V1 (points): the 6th/7th bonuses of the wiki round 2 (the owner, 3 November 2026;
	// server-patches/bonusy67b, playerbot_bonus67.cpp) - the last three numbers an item's bonus type (one byte) has.
	// Sent to the client as point changes (an exe with POINT_MAX_NUM 256 shows them in the bonus window; an older
	// one drops a type >= its 253 in CPythonPlayer::SetStatus); the item tooltip names them (root/localeinfo_point.py).
#define MT2009_PLUS_BONUS67_WIKI
	POINT_RESIST_COMBAT,	// 253 "Jesli masz powyzej 90% PZ, doznajesz obrazenia nizsze o x%" (body armour)
	POINT_BLEEDING_PCT,	// 254 "Atak krwawienia +x%" - x% chance a normal hit makes the victim bleed
	POINT_BLEEDING_REDUCE,	// 255 "Odpornosc na atak krwawienia +x%" - the bleeding's damage x 2% lower
	POINT_MAX_NUM,	// 256 (an item keeps its bonus type in one byte: all 256 taken)

if (pkAttacker->GetPoint(POINT_POISON_PCT) && !pkVictim->IsAffectFlag(AFF_POISON))
{
	if (number(1, 100) <= pkAttacker->GetPoint(POINT_POISON_PCT))
		pkVictim->AttackedByPoison(pkAttacker);
}
{ // MT2009_PLUS_BONUS67_WIKI_V1 (bleeding): "Atak krwawienia" of the 6th/7th bonuses (playerbot_bonus67.cpp)
	void Bonus67Bleeding(LPCHARACTER pkAttacker, LPCHARACTER pkVictim);
	Bonus67Bleeding(pkAttacker, pkVictim);
}

if (ch->IsAffectFlag(AFF_POISON))
	return PASSES_PER_SEC(MAX(1, ch->GetMobTable().bRegenCycle));
{ // MT2009_PLUS_BONUS67_WIKI_V1 (regen npc): a bleeding monster does not regenerate (playerbot_bonus67.cpp)
	bool Bonus67IsBleeding(const CHARACTER* ch);
	if (Bonus67IsBleeding(ch))
		return PASSES_PER_SEC(MAX(1, ch->GetMobTable().bRegenCycle));
}

if (ch->IsAffectFlag(AFF_POISON) == true)
{
	return 3;
}
{ // MT2009_PLUS_BONUS67_WIKI_V1 (regen pc): a bleeding character does not regenerate (playerbot_bonus67.cpp)
	bool Bonus67IsBleeding(const CHARACTER* ch);
	if (Bonus67IsBleeding(ch))
		return 3;
}
